import java.util.*;

class Solution {
    private Map<Integer, List<String>> memo = new HashMap<>();

    public List<String> fullTreeShapes(int n) {
        return build(n);
    }

    private List<String> build(int m) {
        if (memo.containsKey(m)) return memo.get(m);
        List<String> res = new ArrayList<>();
        if (m == 1) res.add("o");
        else if (m % 2 == 1) {
            for (int left = 1; left < m - 1; left += 2)      // odd sizes only
                for (String a : build(left))
                    for (String b : build(m - 1 - left))
                        res.add("x" + a + b);              // root, left, right
        }
        memo.put(m, res);
        return res;
    }
}

