class Solution:
    def fullTreeShapes(self, n: int) -> List[str]:
        @lru_cache(maxsize=None)
        def build(m):
            if m == 1: return ("o",)
            if m % 2 == 0: return ()
            res = []
            for left in range(1, m - 1, 2):
                for a in build(left):
                    for b in build(m - 1 - left): res.append("x" + a + b)
            return tuple(res)
        return list(build(n))

