function fullTreeShapes(n) {
  // generate preorder strings directly: need = number of open leaf slots
  if (n % 2 === 0) return [];
  const out = [], internals = (n - 1) / 2;
  (function go(s, x, slots) {
    if (slots === 0) { if (s.length === n) out.push(s); return; }
    if (x < internals) go(s + "x", x + 1, slots + 1);
    if (s.length - x < internals + 1) go(s + "o", x, slots - 1);
  })("", 0, 1);
  return out;
}
